package net.civeira.phylax.common.security;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNotEquals;
import static org.junit.jupiter.api.Assertions.assertSame;

import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.security.impl.ActorImpl;
import net.civeira.phylax.common.security.impl.AuthenticationContextImpl;
import net.civeira.phylax.common.security.impl.InvocationSourceImpl;

@DisplayName("Security value holders")
class SecurityContextAccessorsUnitTest {

  private final Actor actor = ActorImpl.builder().uid("u-1").build();
  private final InvocationSource source = InvocationSourceImpl.builder().build();
  private final AuthenticationContext auth = AuthenticationContextImpl.builder().build();
  private final OperationContext context = new OperationContext(actor, source, auth);

  @Test
  @DisplayName("AuthorizationDecision should expose the invocation source")
  void authorizationDecisionShouldExposeSource() {
    AuthorizationDecision decision = new AuthorizationDecision(context, Permission.allow()) {
      @Override
      public String resourceName() {
        return "resource";
      }

      @Override
      public String actionName() {
        return "action";
      }
    };
    assertSame(source, decision.getSource());
  }

  @Test
  @DisplayName("PropertiesProposal should expose the invocation source")
  void propertiesProposalShouldExposeSource() {
    PropertiesProposal proposal = new PropertiesProposal(context) {
      @Override
      public String resourceName() {
        return "resource";
      }

      @Override
      public String viewName() {
        return "view";
      }
    };
    assertSame(source, proposal.getSource());
  }

  @Test
  @DisplayName("MagicLinkResult should hold its components")
  void magicLinkResultShouldHoldComponents() {
    MagicLinkResult result = new MagicLinkResult("jwt", actor, auth, source);
    assertEquals("jwt", result.jwtToken());
    assertSame(actor, result.actor());
    assertSame(auth, result.auth());
    assertSame(source, result.source());
    assertEquals(result, new MagicLinkResult("jwt", actor, auth, source));
    assertNotEquals(result, new MagicLinkResult("other", actor, auth, source));
  }
}
